#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

static int view_total(const int values[], size_t count)
{
    int total = 0;
    for (size_t i = 0; i < count; ++i) {
        total += values[i];
    }
    return total;
}

static void release_values(int **owner, unsigned *releases)
{
    if (*owner != NULL) {
        free(*owner);
        *owner = NULL;
        ++*releases;
    }
}

int main(void)
{
    const size_t count = 2;
    if (count > SIZE_MAX / sizeof(int)) {
        puts("size-error");
        return 0;
    }
    int *owner = malloc(count * sizeof *owner);
    if (owner == NULL) {
        puts("allocation-failed");
        return 0;
    }
    owner[0] = 4;
    owner[1] = 5;
    printf("total %d\n", view_total(owner, count));

    unsigned releases = 0;
    release_values(&owner, &releases);
    release_values(&owner, &releases);
    printf("releases %u\n", releases);
    return 0;
}

