#include <stdint.h>
#include <ctype.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>

static int read_values(int values[], const int minimum[], const int maximum[], size_t count)
{
    char line[64];
    size_t length = 0;
    int ch;
    while ((ch = getchar()) != EOF && ch != '\n') {
        if (ch == 0 || length == sizeof line - 1) {
            return 0;
        }
        line[length++] = (char)ch;
    }
    if (ferror(stdin)) {
        return 0;
    }
    line[length] = '\0';

    char *cursor = line;
    for (size_t i = 0; i < count; ++i) {
        char *end;
        errno = 0;
        long value = strtol(cursor, &end, 10);
        if (end == cursor || errno == ERANGE || value < minimum[i] || value > maximum[i]) {
            return 0;
        }
        if (i + 1 < count && !isspace((unsigned char)*end)) {
            return 0;
        }
        values[i] = (int)value;
        cursor = end;
    }
    while (isspace((unsigned char)*cursor)) {
        ++cursor;
    }
    return *cursor == '\0';
}

static void release_values(int **owner, unsigned *released)
{
    if (*owner != NULL) {
        free(*owner);
        *owner = NULL;
        /* TODO: count the release that actually happened. */
        *released += 0;
    }
}

static int sum_values(const int values[], size_t count)
{
    int sum = 0;
    for (size_t i = 0; i < count; ++i) {
        sum += values[i];
    }
    return sum;
}

int main(void)
{
    unsigned released = 0;
    int input[2];
    const int minimum[] = {1, 0};
    const int maximum[] = {16, 1};
    if (!read_values(input, minimum, maximum, 2)) {
        puts("invalid");
        printf("released %u\n", released);
        return 0;
    }
    size_t count = (size_t)input[0];
    if (count > SIZE_MAX / sizeof(int)) {
        puts("size-error");
        printf("released %u\n", released);
        return 0;
    }
    int *owner = malloc(count * sizeof *owner);
    if (owner == NULL) {
        puts("allocation-failed");
        printf("released %u\n", released);
        return 0;
    }
    for (size_t i = 0; i < count; ++i) {
        owner[i] = (int)i + 1;
    }
    if (input[1] == 0) {
        puts("rejected");
    } else {
        printf("sum %d\n", sum_values(owner, count));
    }
    release_values(&owner, &released);
    release_values(&owner, &released);
    printf("released %u\n", released);
    return 0;
}

